description:
Apply the Microsoft x64 calling convention (lesson 2.01):

```cpp
enum class Kind { Integer, Floating };

std::vector<std::string> argumentLocations(const std::vector<Kind>& args);
std::string returnLocation(Kind result);
bool isVolatile(const std::string& reg);
```

- **argumentLocations** gives where each argument is **on entry** to the function. Position decides the register: the first four go in `rcx`, `rdx`, `r8`, `r9` if they are integers or pointers, or `xmm0` to `xmm3` if floating point. Later arguments are on the stack: the 5th at `[rsp+0x28]`, the 6th at `[rsp+0x30]`, and so on in steps of 8, whatever their kind.
- **returnLocation** is `rax` for integers and `xmm0` for floating point.
- **isVolatile** is true for registers a call may destroy: `rax`, `rcx`, `rdx`, `r8` to `r11`, and `xmm0` to `xmm5`. Everything else (`rbx`, `rbp`, `rdi`, `rsi`, `rsp`, `r12` to `r15`, `xmm6` to `xmm15`) is non-volatile.

starter.solution.cpp:
#include <string>
#include <vector>

enum class Kind { Integer, Floating };

std::vector<std::string> argumentLocations(const std::vector<Kind>& args) { return {}; }
std::string returnLocation(Kind result) { return ""; }
bool isVolatile(const std::string& reg) { return false; }

solution.solution.cpp:
#include <string>
#include <vector>

enum class Kind { Integer, Floating };

static std::string hex(unsigned value)
{
    static const char* const HEX{ "0123456789abcdef" };
    std::string out;
    do { out.insert(out.begin(), HEX[value & 0xF]); value >>= 4; } while (value);
    return out;
}

std::vector<std::string> argumentLocations(const std::vector<Kind>& args)
{
    static const char* const ints[]{ "rcx", "rdx", "r8", "r9" };
    std::vector<std::string> out;
    for (std::size_t i{ 0 }; i < args.size(); ++i)
    {
        if (i < 4) out.push_back(args[i] == Kind::Floating ? "xmm" + std::to_string(i) : ints[i]);
        else out.push_back("[rsp+0x" + hex(static_cast<unsigned>(0x28 + 8 * (i - 4))) + "]");
    }
    return out;
}

std::string returnLocation(Kind result) { return result == Kind::Floating ? "xmm0" : "rax"; }

bool isVolatile(const std::string& reg)
{
    for (const char* r : { "rax", "rcx", "rdx", "r8", "r9", "r10", "r11", "xmm0", "xmm1", "xmm2", "xmm3", "xmm4", "xmm5" })
        if (reg == r) return true;
    return false;
}

unitTests:
using S = std::vector<std::string>;
TEST("all integers") {
    CHECK_EQ(argumentLocations({ Kind::Integer, Kind::Integer }), (S{ "rcx", "rdx" }));
    CHECK_EQ(argumentLocations({ Kind::Integer, Kind::Integer, Kind::Integer, Kind::Integer, Kind::Integer, Kind::Integer }),
             (S{ "rcx", "rdx", "r8", "r9", "[rsp+0x28]", "[rsp+0x30]" }));
    CHECK(argumentLocations({}).empty());
}
TEST("position decides the register") {
    CHECK_EQ(argumentLocations({ Kind::Integer, Kind::Floating, Kind::Integer }), (S{ "rcx", "xmm1", "r8" }));
    CHECK_EQ(argumentLocations({ Kind::Floating, Kind::Floating, Kind::Floating, Kind::Floating, Kind::Floating }),
             (S{ "xmm0", "xmm1", "xmm2", "xmm3", "[rsp+0x28]" }));
    const auto many{ argumentLocations(std::vector<Kind>(9, Kind::Integer)) };
    CHECK_EQ(many.back(), std::string("[rsp+0x48]"));
}
TEST("return values") {
    CHECK_EQ(returnLocation(Kind::Integer), std::string("rax"));
    CHECK_EQ(returnLocation(Kind::Floating), std::string("xmm0"));
}
TEST("volatile registers") {
    for (const char* r : { "rax", "rcx", "r11", "xmm5", "r8" }) CHECK(isVolatile(r));
    for (const char* r : { "rbx", "rbp", "rsi", "rdi", "rsp", "r12", "r15", "xmm6", "xmm15" }) CHECK(!isVolatile(r));
}

